function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof MYSORE_INFO&&(n.innerHTML=MYSORE_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderCoins(){const n=document.getElementById("coins-grid");n&&"undefined"!=typeof COIN_DENOMINATIONS&&(n.innerHTML=COIN_DENOMINATIONS.map(n=>`\n        <div class="coin-card">\n            <h3>🪙 ${n.name}</h3>\n            <span class="coin-period-tag">${n.period}</span>\n            <p><strong>Metal & Weight:</strong> ${n.metal}</p>\n            <p><strong>Naming Etymology:</strong> ${n.namedAfter}</p>\n            <p><strong>Obverse:</strong> <em>"${n.obverseText}"</em></p>\n            <p><strong>Reverse:</strong> <em>"${n.reverseText}"</em></p>\n            <p class="coin-sig"><strong>Significance:</strong> ${n.significance}</p>\n        </div>\n    `).join(""))}function initConverter(){const n=document.getElementById("btn-convert"),e=document.getElementById("mauludi-input"),t=document.getElementById("convert-result");n&&e&&t&&n.addEventListener("click",()=>{const n=parseInt(e.value,10);if(isNaN(n)||n<1e3||n>1500)return void(t.textContent="Please enter a valid Mauludi Year (e.g. 1216).");const i=n-1200+1772;t.innerHTML=`☀️ <strong>Mauludi Year ${n}</strong> corresponds to approximately <strong>${i} CE</strong> in the Gregorian calendar.`})}function renderMints(){const n=document.getElementById("mints-grid");n&&"undefined"!=typeof MINTS_LIST&&(n.innerHTML=MINTS_LIST.map(n=>`\n        <div class="mint-card">\n            <h3>🏛️ ${n.name}</h3>\n            <span class="mint-code">Mint Mark: ${n.code}</span>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderTimeline(){const n=document.getElementById("timeline-container");n&&"undefined"!=typeof TIMELINE_EVENTS&&(n.innerHTML=TIMELINE_EVENTS.map(n=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${n.year}</div>\n            <div class="timeline-content">\n                <h3>${n.title}</h3>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderCoins(),initConverter(),renderMints(),renderTimeline(),renderReferences(),initThemeToggle()});